   121→impl StreamingServer for DefaultStreamingServer {
   122→    async fn start(&self, config: &StreamingConfig) -> Result<(), StreamingError> {
   123→        if !config.enabled {
   124→            return Err(StreamingError::BindFailed(
   125→                "Streaming is disabled".to_string(),
   126→            ));
   127→        }
   128→
   129→        *self.config.write().await = Some(config.clone());
   130→
   131→        // Generate PIN if required
   132→        if config.require_pin {
   133→            self.pin_auth.generate_pin();
   134→        }
   135→
   136→        // Build server URL
   137→        let ip = Self::get_local_ip().unwrap_or_else(|| "localhost".to_string());
   138→        let url = format!("http://{}:{}", ip, config.port);
   139→        *self.server_url.write().await = Some(url.clone());
   140→
   141→        tracing::info!("Starting streaming server on port {}", config.port);
   142→
   143→        // TODO: Actually start the WebSocket server using tokio-tungstenite
   144→        // let addr = format!("0.0.0.0:{}", config.port);
   145→        // let listener = TcpListener::bind(&addr).await
   146→        //     .map_err(|e| StreamingError::BindFailed(e.to_string()))?;
   147→
   148→        *self.is_running.write().await = true;
   149→
   150→        let _ = self.event_tx.send(StreamingEvent::ServerStarted { url });
   151→
   152→        Ok(())
   153→    }
   154→
   155→    async fn stop(&self) -> Result<(), StreamingError> {
   156→        // Disconnect all sessions
   157→        let sessions: Vec<Uuid> = self.sessions.read().await.keys().cloned().collect();
   158→        for session_id in sessions {
   159→            let _ = self.disconnect_session(&session_id).await;
   160→        }
   161→
   162→        *self.is_running.write().await = false;
   163→        *self.server_url.write().await = None;
   164→
   165→        let _ = self.event_tx.send(StreamingEvent::ServerStopped);
   166→
   167→        tracing::info!("Streaming server stopped");
   168→
   169→        Ok(())
   170→    }
   171→
   172→    fn is_running(&self) -> bool {
   173→        self.is_running.try_read().map(|r| *r).unwrap_or(false)
   174→    }
   175→
   176→    fn get_url(&self) -> Option<String> {
   177→        self.server_url.try_read().ok()?.clone()
   178→    }
   179→
   180→    fn get_qr_code(&self) -> Option<QrCodeData> {
   181→        let url = self.get_url()?;
   182→        Some(Self::generate_qr_code(&url))
   183→    }
   184→
   185→    fn regenerate_pin(&self) -> String {
   186→        self.pin_auth.regenerate()
   187→    }
   188→
   189→    fn get_pin(&self) -> Option<String> {
   190→        self.pin_auth.get_current_pin()
   191→    }
   192→
   193→    fn get_sessions(&self) -> Vec<StreamingSession> {
   194→        self.sessions
   195→            .try_read()
   196→            .map(|s| s.values().cloned().collect())
   197→            .unwrap_or_default()
   198→    }
   199→
   200→    async fn disconnect_session(&self, session_id: &Uuid) -> Result<(), StreamingError> {
   201→        let mut sessions = self.sessions.write().await;
   202→
   203→        if sessions.remove(session_id).is_some() {
   204→            let _ = self.event_tx.send(StreamingEvent::ClientDisconnected {
   205→                session_id: *session_id,
   206→            });
   207→            Ok(())
   208→        } else {
   209→            Err(StreamingError::SessionNotFound(*session_id))
   210→        }
   211→    }
   212→
   213→    fn broadcast_metrics(&self, metrics: &StreamingMetrics) {
   214→        // Send to all connected clients
   215→        let _ = self.metrics_tx.send(metrics.clone());
   216→    }
   217→
   218→    fn subscribe_events(&self) -> broadcast::Receiver<StreamingEvent> {
   219→        self.event_tx.subscribe()
   220→    }
   221→}
