   158→/// Run the daemon with the given configuration
   159→pub async fn run_daemon(config: DaemonConfig) -> anyhow::Result<()> {
   160→    info!("Starting RustRide daemon...");
   161→
   162→    // Create socket directory if needed
   163→    if let Some(parent) = config.socket_path.parent() {
   164→        std::fs::create_dir_all(parent)?;
   165→    }
   166→
   167→    // Create PID file directory if needed
   168→    if let Some(parent) = config.pid_path.parent() {
   169→        std::fs::create_dir_all(parent)?;
   170→    }
   171→
   172→    // Write PID file (for foreground mode - daemonize() handles it for background)
   173→    if config.foreground {
   174→        std::fs::write(&config.pid_path, format!("{}", std::process::id()))?;
   175→    }
   176→
   177→    // T072: Check for incomplete rides from previous sessions
   178→    let incomplete_rides = check_incomplete_rides();
   179→
   180→    // Initialize daemon state
   181→    let state = Arc::new(RwLock::new(DaemonState::new()));
   182→
   183→    // Update state with paths and register incomplete rides
   184→    {
   185→        let mut state_guard = state.write().await;
   186→        state_guard.socket_path = Some(config.socket_path.clone());
   187→        state_guard.log_path = config.log_path.clone();
   188→        state_guard.incomplete_rides = incomplete_rides;
   189→        state_guard.set_running();
   190→    }
   191→
   192→    // T066: Auto-connect to preferred sensors
   193→    auto_connect_preferred_sensors(state.clone()).await;
   194→
   195→    // Start IPC server
   196→    let server = IpcServer::new(&config.socket_path, state.clone()).await?;
   197→
   198→    // Setup signal handlers
   199→    let shutdown_signal = signals::setup_signal_handlers()?;
   200→
   201→    info!("Daemon listening on {:?}", config.socket_path);
   202→
   203→    // T076: Start auto-save checkpoint task
   204→    let autosave_state = state.clone();
   205→    let autosave_interval = load_daemon_config().autosave_interval_secs;
   206→    let autosave_task = tokio::spawn(async move {
   207→        run_autosave_loop(autosave_state, autosave_interval).await;
   208→    });
   209→
   210→    // Run server until shutdown signal
   211→    tokio::select! {
   212→        result = server.run() => {
   213→            if let Err(e) = result {
   214→                error!("Server error: {}", e);
   215→            }
   216→        }
   217→        _ = shutdown_signal => {
   218→            info!("Received shutdown signal");
   219→        }
   220→    }
   221→
   222→    // Cancel autosave task
   223→    autosave_task.abort();
   224→
   225→    // Graceful shutdown
   226→    info!("Shutting down daemon...");
   227→    {
   228→        let mut state = state.write().await;
   229→        state.initiate_shutdown();
   230→    }
   231→
   232→    // Cleanup socket file
   233→    if config.socket_path.exists() {
   234→        let _ = std::fs::remove_file(&config.socket_path);
   235→    }
   236→
   237→    // Cleanup PID file
   238→    if config.pid_path.exists() {
   239→        let _ = std::fs::remove_file(&config.pid_path);
   240→    }
   241→
   242→    info!("Daemon stopped");
   243→    Ok(())
   244→}
